// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { CheckIcon, CopyIcon } from 'lucide-react'
import { Fragment } from 'react'

import {
  BrowserChrome,
  DemoStage,
  DockHeader,
  mockImage,
  type Build,
} from '@/app/demos/stage'

import { ARTICLE, type Block, CAPTIONS, EDIT, LINES, SELECTED, SELECTION_MD } from './script'

const build: Build = ({ tl, q, qa, pos, step, final, move, click, type, wait, cursorOut }) => {
  const passage = pos(`blk-${SELECTED}`, 0, 0)
  tl.set(
    q('sel'),
    { x: passage.x - 2, y: passage.y - 1, width: passage.w + 4, height: passage.h + 2 },
    0,
  )

  step(0)
  move(`blk-${SELECTED}`, { ax: 0, ay: 0.1, at: 0.2 })
  tl.fromTo(
    q('sel'),
    { opacity: 1, clipPath: 'inset(0% 100% 0% 0%)' },
    { clipPath: 'inset(0% 0% 0% 0%)', duration: 0.8, ease: 'power1.inOut' },
    '>',
  )
  move(`blk-${SELECTED}`, { ax: 0.95, ay: 0.9, at: '<', duration: 0.8 })

  step(1, '+=0.3')
  move('from-selection')
  click('from-selection')
  tl.fromTo(q('ta-sel'), { opacity: 0, y: 6 }, { opacity: 1, y: 0, duration: 0.3 }, '<0.1')

  step(2, '+=0.5')
  move('from-article')
  click('from-article')
  tl.to(q('sel'), { opacity: 0, duration: 0.2 }, '<')
  tl.to(q('ta-sel'), { opacity: 0, duration: 0.2 }, '<')
  tl.fromTo(
    q('source'),
    { clipPath: 'inset(0% 0% 100% 0%)' },
    { clipPath: 'inset(0% 0% 0% 0%)', duration: 1, ease: 'power2.inOut' },
    '<0.1',
  )
  tl.fromTo(
    qa('line'),
    { opacity: 0, x: -6 },
    { opacity: 1, x: 0, duration: 0.2, stagger: 0.06 },
    '<0.2',
  )
  tl.to(
    q('source'),
    { clipPath: 'inset(100% 0% 0% 0%)', duration: 0.8, ease: 'power2.inOut' },
    '+=0.5',
  )

  step(3, '+=0.2')
  move('line-0', { ax: 1, dx: 4 })
  click('line-0')
  type('line-0', `${LINES[0]}${EDIT}`, { speed: 0.05 })
  move('copy', { at: '+=0.2' })
  click('copy')
  tl.to(q('copy-icon'), { opacity: 0, duration: 0.1 }, '<')
  tl.fromTo(
    q('copy-done'),
    { opacity: 0, scale: 0.5 },
    { opacity: 1, scale: 1, duration: 0.25, ease: 'back.out(3)' },
    '<',
  )
  cursorOut('+=0.2')
  final()
  wait(1.4)
}

function Inline({ block }: { block: Extract<Block, { inline: unknown }> }) {
  return (
    <>
      {block.inline.map((part, index) =>
        typeof part === 'string' ? (
          <Fragment key={index}>{part}</Fragment>
        ) : part.tag === 'a' ? (
          <span key={index} className="text-[#7c3aed] underline">
            {part.text}
          </span>
        ) : part.tag === 'code' ? (
          <code key={index} className="rounded bg-black/5 px-0.5 font-mono">
            {part.text}
          </code>
        ) : (
          <strong key={index}>{part.text}</strong>
        ),
      )}
    </>
  )
}

function Page() {
  return (
    <article className="h-full space-y-2 bg-[#fafafa] px-4 pt-3 text-[9px] leading-relaxed text-[#444]">
      {ARTICLE.map((block, index) => {
        const d = `blk-${index}`
        if (block.tag === 'h1')
          return (
            <h3
              key={index}
              data-d={d}
              className="text-[15px] font-bold leading-tight tracking-tight text-[#111]"
            >
              <Inline block={block} />
            </h3>
          )
        if (block.tag === 'h2')
          return (
            <h4 key={index} data-d={d} className="text-[11px] font-semibold text-[#111]">
              <Inline block={block} />
            </h4>
          )
        if (block.tag === 'p')
          return (
            <p key={index} data-d={d}>
              <Inline block={block} />
            </p>
          )
        if (block.tag === 'img')
          return (
            <div
              key={index}
              data-d={d}
              className="h-12 rounded-md"
              style={{ background: mockImage(1) }}
            />
          )
        if (!('items' in block)) return null
        return (
          <ul key={index} data-d={d} className="list-disc space-y-0.5 pl-3.5">
            {block.items.map((item, itemIndex) => (
              <li key={itemIndex}>
                <Inline block={{ tag: 'p', inline: item }} />
              </li>
            ))}
          </ul>
        )
      })}
    </article>
  )
}

export default function Demo() {
  return (
    <DemoStage
      label="Copy as Markdown turning a selection, then a whole article, into editable Markdown"
      steps={CAPTIONS}
      build={build}
    >
      <BrowserChrome
        url="https://northwind.app/blog/builds"
        panelWidth={246}
        panel={
          <div className="flex h-full flex-col">
            <DockHeader />
            <div className="flex min-h-0 flex-1 flex-col gap-2 p-2">
              <div className="flex gap-1.5">
                {(
                  [
                    ['from-selection', 'From selection'],
                    ['from-article', 'From article'],
                  ] as const
                ).map(([d, label]) => (
                  <span
                    key={d}
                    data-d={d}
                    className="rounded-md bg-white/[0.08] px-2 py-1 text-[9.5px] text-ink"
                  >
                    {label}
                  </span>
                ))}
              </div>
              <div className="relative min-h-0 flex-1 overflow-hidden rounded-md border border-line bg-canvas/80 p-1.5 font-mono text-[8px] leading-[11px]">
                <p
                  data-d="ta-sel"
                  className="absolute inset-1.5 whitespace-pre-wrap text-ink opacity-0"
                >
                  {SELECTION_MD}
                </p>
                {LINES.map((line, index) => (
                  <p
                    key={index}
                    data-d={`line line-${index}`}
                    className="min-h-[11px] whitespace-pre-wrap break-words text-ink opacity-0"
                  >
                    {line}
                  </p>
                ))}
              </div>
              <span
                data-d="copy"
                className="flex w-fit items-center gap-1 rounded-md border border-line-strong px-2 py-1 text-[9.5px] text-ink-soft"
              >
                <span className="relative size-3">
                  <span data-d="copy-icon" className="absolute inset-0">
                    <CopyIcon className="size-3" />
                  </span>
                  <span
                    data-d="copy-done"
                    className="absolute inset-0 text-[var(--accent)] opacity-0"
                  >
                    <CheckIcon className="size-3" />
                  </span>
                </span>
                Copy
              </span>
            </div>
          </div>
        }
      >
        <Page />
        <div
          data-d="source"
          className="absolute inset-0 overflow-hidden bg-[#0f0f16] px-4 pt-3 font-mono text-[9px] leading-[14px] text-ink-soft [clip-path:inset(0_0_100%_0)]"
        >
          {LINES.map((line, index) => (
            <p
              key={index}
              className="min-h-[14px] whitespace-pre-wrap break-words"
              style={{ color: /^(#|- |!\[)/.test(line) ? '#fb923c' : undefined }}
            >
              {line}
            </p>
          ))}
        </div>
      </BrowserChrome>
      <span
        data-d="sel"
        className="pointer-events-none absolute left-0 top-0 z-20 rounded-sm bg-[rgba(56,189,248,0.3)] opacity-0"
      />
    </DemoStage>
  )
}
